window.AUTH=window.AUTH||{};window.AUTH["17-773"]={"d":"17-773","id":"2018/17-773","n":"Culbertson v. Berryhill","briefs":[{"k":"petitioner","label":"Brief of petitioner Richard Culbertson","date":"2018-07-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-773/54301/20180716130124603_17-773%20Apellants%20Brief.pdf","side":"pet","n":34},{"k":"respondent","label":"Brief of respondent Nancy A. Berryhill, Deputy Commissioner for Operations, Social Security Administration in support of reversal and remand","date":"2018-07-16","url":"https://www.supremecourt.gov/DocketPDF/17/17-773/54403/20180716170642175_17-773tsUnitedStates.pdf","side":"res","n":52},{"k":"reply","label":"Reply of petitioner Richard Culbertson","date":"2018-10-09","url":"https://www.supremecourt.gov/DocketPDF/17/17-773/66257/20181009153714545_17-773_Reply%20Brief.pdf","side":"pet","n":36}],"opinion":"https://www.supremecourt.gov/opinions/18pdf/17-773_4h25.pdf","tr":true,"items":[{"t":"case","label":"Bookman v. Commissioner of Soc. Sec.","cite":"490 F. Appx. 314","y":2012,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20Appx./490/314/","by":{"0":"5"}},{"t":"case","label":"Carcieri v. Salazar","cite":"555 U.S. 379","y":2009,"id":"2008/07-526","sc":1,"sum":"The Court found that only tribes under federal jurisdiction at the time of the Indian Reorganization Act of 1934 are subject to taking by the federal government.","sumSrc":"Oyez","by":{"0":"6"}},{"t":"case","label":"Caminetti v. United States","cite":"242 U.S. 470","y":1917,"id":"scdb/1916-190","sc":1,"sum":"The White Slave Traffic Act of June 25, 1910, c. 395, 36 Stat. 825, applies to any case in which a woman is transported in interstate commerce for the purpose of prostitution or concubinage; pecuniary gain, either as a motive for the transportation or as an attendant of its object, is not an element in the offenses defined.","sumSrc":"Headnote (U.S. Reports)","by":{"0":"11"}},{"t":"case","label":"Clark v. Astrue","cite":"529 F.3d 1211","y":2008,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/529/1211/","by":{"0":"15","1":"22","2":"17"}},{"t":"case","label":"Connecticut Nat’l Bank v. Germain","cite":"503 U.S. 249","y":1992,"id":"1991/90-1791","sc":1,"sum":"An interlocutory order issued by a district court sitting as a court of appeals in bankruptcy is appealable under the unambiguous language of 28 U. S. C. § 1292. That section provides for review in the courts of appeals, in certain circumstances, of \"[i]nterlocutory orders of the district courts,\" and does not limit such review to orders issued by district courts sitting as bankruptcy trial courts rather than …","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12, 13, 18"}},{"t":"case","label":"Crawford v. Astrue","cite":"586 F.3d 1142","y":2009,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/586/1142/","by":{"0":"24","2":"16"}},{"t":"case","label":"Dawson v. Finch","cite":"425 F.2d 1192","y":1970,"court":"5th Cir.","url":"https://www.courtlistener.com/c/F.2d/425/1192/","op":1,"ar":2,"by":{"0":"4, 27","1":"13, 19, 20"}},{"t":"case","label":"Department of Homeland Sec. v. MacLean","cite":"135 S. Ct. 913","y":2015,"id":"2014/13-894","sc":1,"sum":"The Court ruled that the Whistleblower Protection Act bars an agency from taking enforcement action against employees who intentionally disclose sensitive security information.","sumSrc":"Oyez","by":{"0":"12"}},{"t":"case","label":"Gisbrecht v. Barnhart","cite":"535 U.S. 789","y":2002,"id":"2001/01-131","sc":1,"op":2,"ar":5,"sum":"The Court held that section 406(b) does not displace contingent-fee agreements within the statutory ceiling; instead, section 406(b) instructs courts to review for reasonableness fees yielded by those agreements.","sumSrc":"Oyez","by":{"0":"passim","1":"2, 3, 8, 13, 14, 25","2":"20"}},{"t":"case","label":"Morris v. Social Sec. Admin.","cite":"689 F.2d 495","y":1982,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/689/495/","op":16,"ar":8,"by":{"0":"27","1":"19, 21"}},{"t":"case","label":"NLRB v. SW Gen., Inc.","cite":"137 S. Ct. 929","y":2017,"id":"2016/15-1251","sc":1,"sum":"The Court determined that the limitations on nominees to vacant positions serving in an acting capacity under the Federal Vacancies Reform Act apply equally to first assistants who take on the position and to those who are selected by the President from within the same agency or from another agency.","sumSrc":"Oyez","by":{"0":"10, 27"}},{"t":"case","label":"Paltan v. Commissioner of Soc. Sec.","cite":"518 F. Appx. 673","y":2013,"court":"11th Cir.","url":"https://www.courtlistener.com/c/F.%20Appx./518/673/","by":{"0":"5"}},{"t":"case","label":"Parrish v. Commissioner of Soc. Sec. Admin.","cite":"698 F.3d 1215","y":2012,"court":"9th Cir.","url":"https://www.courtlistener.com/c/F.3d/698/1215/","by":{"0":"3, 4"}},{"t":"case","label":"Rubin v. United States","cite":"449 U.S. 424","y":1981,"id":"1980/79-1013","sc":1,"sum":"The pledge of stock to a bank as collateral for a loan is an \"offer or sale\" of a security under § 17 (a).","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"13, 27"}},{"t":"case","label":"Russello v. United States","cite":"464 U.S. 16","y":1983,"id":"1983/82-472","sc":1,"sum":"The insurance proceeds petitioner received as a result of his arson activities constitute an \"interest\" within the meaning of § 1963(a)(1) and are therefore subject to forfeiture.","sumSrc":"Syllabus (U.S. Reports)","by":{"0":"12","1":"17"}},{"t":"case","label":"State Farm Fire & Cas. Co. v. United States ex rel. Rigsby","cite":"137 S. Ct. 436","y":2016,"id":"2016/15-513","sc":1,"sum":"The Court determined that a violation of the False Claims Act’s seal requirement does not mandate dismissal of the complaint.","sumSrc":"Oyez","by":{"0":"10"}},{"t":"case","label":"Washington State Dep’t of Soc. & Health Servs. v. Guardianship Estate of Keffeler","cite":"537 U.S. 371","y":2003,"id":"2002/01-1420","sc":1,"sum":"The Court held that the state's use of the Social Security benefits to reimburse itself does not violate the Social Security Act's anti-attachment provision.","sumSrc":"Oyez","by":{"0":"16","1":"9","2":"21"}},{"t":"usc","label":"28 U.S.C. § 1254","url":"https://www.law.cornell.edu/uscode/text/28/1254","subs":["(1)"],"by":{"0":"1"}},{"t":"usc","label":"28 U.S.C. § 2412","url":"https://www.law.cornell.edu/uscode/text/28/2412","subs":["(d)(1)(A)","(d)","(d)(2)(A)"],"stext":{"head":"§2412. Costs and fees","paras":[[0,"(a)(1) Except as otherwise specifically provided by statute, a judgment for costs, as enumerated in section 1920 of this title, but not including the fees and expenses of attorneys, may be awarded to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. A judgment for costs when taxed against the United States shall, in an amount established by statute, court rule, or order, be limited to reimbursing in whole or in part the prevailing party for the costs incurred by such party in the litigation."],[0,"(2) A judgment for costs, when awarded in favor of the United States in an action brought by the United States, may include an amount equal to the filing fee prescribed under section 1914(a) of this title. The preceding sentence shall not be construed as requiring the United States to pay any filing fee."],[0,"(b) Unless expressly prohibited by statute, a court may award reasonable fees and expenses of attorneys, in addition to the costs which may be awarded pursuant to subsection (a), to the prevailing party in any civil action brought by or against the United States or any agency or any official of the United States acting in his or her official capacity in any court having jurisdiction of such action. The United States shall be liable for such fees and expenses to the same extent that any other party would be liable under the common law or under the terms of any statute which specifically provides for such an award."],[0,"(c)(1) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for costs pursuant to subsection (a) shall be paid as provided in sections 2414 and 2517 of this title and shall be in addition to any relief provided in the judgment."],[0,"(2) Any judgment against the United States or any agency and any official of the United States acting in his or her official capacity for fees and expenses of attorneys pursuant to subsection (b) shall be paid as provided in sections 2414 and 2517 of this title, except that if the basis for the award is a finding that the United States acted in bad faith, then the award shall be paid by any agency found to have acted in bad faith and shall be in addition to any relief provided in the judgment."],[0,"(d)(1)(A) Except as otherwise specifically provided by statute, a court shall award to a prevailing party other than the United States fees and other expenses, in addition to any costs awarded pursuant to subsection (a), incurred by that party in any civil action (other than cases sounding in tort), including proceedings for judicial review of agency action, brought by or against the United States in any court having jurisdiction of that action, unless the court finds that the position of the United States was substantially justified or that special circumstances make an award unjust."],[0,"(B) A party seeking an award of fees and other expenses shall, within thirty days of final judgment in the action, submit to the court an application for fees and other expenses which shows that the party is a prevailing party and is eligible to receive an award under this subsection, and the amount sought, including an itemized statement from any attorney or expert witness representing or appearing in behalf of the party stating the actual time expended and the rate at which fees and other expenses were computed. The party shall also allege that the position of the United States was not substantially justified. Whether or not the position of the United States was substantially justified shall be determined on the basis of the record (including the record with respect to the action or failure to act by the agency upon which the civil action is based) which is made in the civil action for which fees and other expenses are sought."],[0,"(C) The court, in its discretion, may reduce the amount to be awarded pursuant to this subsection, or deny an award, to the extent that the prevailing party during the course of the proceedings engaged in conduct which unduly and unreasonably protracted the final resolution of the matter in controversy."],[0,"(D) If, in a civil action brought by the United States or a proceeding for judicial review of an adversary adjudication described in section 504(a)(4) of title 5, the demand by the United States is substantially in excess of the judgment finally obtained by the United States and is unreasonable when compared with such judgment, under the facts and circumstances of the case, the court shall award to the party the fees and other expenses related to defending against the excessive demand, unless the party has committed a willful violation of law or otherwise acted in bad faith, or special circumstances make an award unjust. Fees and expenses awarded under this subparagraph shall be paid only as a consequence of appropriations provided in advance."],[0,"(2) For the purposes of this subsection—"],[1,"(A) \"fees and other expenses\" includes the reasonable expenses of expert witnesses, the reasonable cost of any study, analysis, engineering report, test, or project which is found by the court to be necessary for the preparation of the party's case, and reasonable attorney fees (The amount of fees awarded under this subsection shall be based upon prevailing market rates for the kind and quality of the services furnished, except that (i) no expert witness shall be compensated at a rate in excess of the highest rate of compensation for expert witnesses paid by the United States; and (ii) attorney fees shall not be awarded in excess of $125 per hour unless the court determines that an increase in the cost of living or a special factor, such as the limited availability of qualified attorneys for the proceedings involved, justifies a higher fee.);"],[1,"(B) \"party\" means (i) an individual whose net worth did not exceed $2,000,000 at the time the civil action was filed, or (ii) any owner of an unincorporated business, or any partnership, corporation, association, unit of local government, or organization, the net worth of which did not exceed $7,000,000 at the time the civil action was filed, and which had not more than 500 employees at the time the civil action was filed; except that an organization described in section 501(c)(3) of the Internal Revenue Code of 1986 (26 U.S.C. 501(c)(3)) exempt from taxation under section 501(a) of such Code, or a cooperative association as defined in section 15(a) of the Agricultural Marketing Act (12 U.S.C. 1141j(a)), may be a party regardless of the net worth of such organization or cooperative association or for purposes of subsection (d)(1)(D), a small entity as defined in section 601 of title 5;"],[1,"(C) \"United States\" includes any agency and any official of the United States acting in his or her official capacity;"],[1,"(D) \"position of the United States\" means, in addition to the position taken by the United States in the civil action, the action or failure to act by the agency upon which the civil action is based; except that fees and expenses may not be awarded to a party for any portion of the litigation in which the party has unreasonably protracted the proceedings;"],[1,"(E) \"civil action brought by or against the United States\" includes an appeal by a party, other than the United States, from a decision of a contracting officer rendered pursuant to a disputes clause in a contract with the Government or pursuant to chapter 71 of title 41;"],[1,"(F) \"court\" includes the United States Court of Federal Claims and the United States Court of Appeals for Veterans Claims;"],[1,"(G) \"final judgment\" means a judgment that is final and not appealable, and includes an order of settlement;"],[1,"(H) \"prevailing party\", in the case of eminent domain proceedings, means a party who obtains a final judgment (other than by settlement), exclusive of interest, the amount of which is at least as close to the highest valuation of the property involved that is attested to at trial on behalf of the property owner as it is to the highest valuation of the property involved that is attested to at trial on behalf of the Government; and"],[1,"(I) \"demand\" means the express demand of the United States which led to the adversary adjudication, but shall not include a recitation of the maximum statutory penalty (i) in the complaint, or (ii) elsewhere when accompanied by an express demand for a lesser amount."],[0,"(3) In awarding fees and other expenses under this subsection to a prevailing party in any action for judicial review of an adversary adjudication, as defined in subsection (b)(1)(C) of section 504 of title 5, or an adversary adjudication subject to chapter 71 of title 41, the court shall include in that award fees and other expenses to the same extent authorized in subsection (a) of such section, unless the court finds that during such adversary adjudication the position of the United States was substantially justified, or that special circumstances make an award unjust."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/28/2412?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§2412. Costs and fees","tname":"Judiciary and Judicial Procedure","by":{"0":"3","1":"2, 2, 2, 2","2":"16"}},{"t":"usc","label":"42 U.S.C. § 306","url":"https://www.law.cornell.edu/uscode/text/42/306","subs":["(a)"],"by":{"0":"20"}},{"t":"usc","label":"42 U.S.C. § 401","url":"https://www.law.cornell.edu/uscode/text/42/401","stext":{"head":"§401. Trust Funds","paras":[[0,"(a) Federal Old-Age and Survivors Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Old-Age and Survivors Insurance Trust Fund\". The Federal Old-Age and Survivors Insurance Trust Fund shall consist of the securities held by the Secretary of the Treasury for the Old-Age Reserve Account and the amount standing to the credit of the Old-Age Reserve Account on the books of the Treasury on January 1, 1940, which securities and amount the Secretary of the Treasury is authorized and directed to transfer to the Federal Old-Age and Survivors Insurance Trust Fund, and, in addition, such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, the Federal Old-Age and Survivors Insurance Trust Fund as hereinafter provided. There is hereby appropriated to the Federal Old-Age and Survivors Insurance Trust Fund for the fiscal year ending June 30, 1941, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1) the taxes (including interest, penalties, and additions to the taxes) received under subchapter A of chapter 9 of the Internal Revenue Code of 1939 (and covered into the Treasury) which are deposited into the Treasury by collectors of internal revenue before January 1, 1951; and"],[1,"(2) the taxes certified each month by the Commissioner of Internal Revenue as taxes received under subchapter A of chapter 9 of such Code which are deposited into the Treasury by collectors of internal revenue after December 31, 1950, and before January 1, 1953, with respect to assessments of such taxes made before January 1, 1951; and"],[1,"(3) the taxes imposed by subchapter A of chapter 9 of such Code with respect to wages (as defined in section 1426 of such Code), and by chapter 21 (other than sections 3101(b) and 3111(b)) of the Internal Revenue Code of 1954 with respect to wages (as defined in section 3121 of such Code) reported to the Commissioner of Internal Revenue pursuant to section 1420(c) of the Internal Revenue Code of 1939 after December 31, 1950, or to the Secretary of the Treasury or his delegates pursuant to subtitle F of the Internal Revenue Code of 1954 after December 31, 1954, as determined by the Secretary of the Treasury by applying the applicable rates of tax under such subchapter or chapter 21 (other than sections 3101(b) and 3111(b)) to such wages, which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports, less the amounts specified in clause (1) of subsection (b) of this section; and"],[1,"(4) the taxes imposed by subchapter E of chapter 1 of the Internal Revenue Code of 1939, with respect to self-employment income (as defined in section 481 of such Code), and by chapter 2 (other than section 1401(b)) of the Internal Revenue Code of 1954 with respect to self-employment income (as defined in section 1402 of such Code) reported to the Commissioner of Internal Revenue on tax returns under such subchapter or to the Secretary of the Treasury or his delegate on tax returns under subtitle F of such Code, as determined by the Secretary of the Treasury by applying the applicable rate of tax under such subchapter or chapter (other than section 1401(b)) to such self-employment income, which self-employment income shall be certified by the Commissioner of Social Security on the basis of the records of self-employment income established and maintained by the Commissioner of Social Security in accordance with such returns, less the amounts specified in clause (2) of subsection (b) of this section."],[0,"The amounts appropriated by clauses (3) and (4) of this subsection shall be transferred from time to time from the general fund in the Treasury to the Federal Old-Age and Survivors Insurance Trust Fund, and the amounts appropriated by clauses (1) and (2) of subsection (b) shall be transferred from time to time from the general fund in the Treasury to the Federal Disability Insurance Trust Fund, such amounts to be determined on the basis of estimates by the Secretary of the Treasury of the taxes, specified in clauses (3) and (4) of this subsection, paid to or deposited into the Treasury; and proper adjustments shall be made in amounts subsequently transferred to the extent prior estimates were in excess of or were less than the taxes specified in such clauses (3) and (4) of this subsection. All amounts transferred to either Trust Fund under the preceding sentence shall be invested by the Managing Trustee in the same manner and to the same extent as the other assets of such Trust Fund. Notwithstanding the preceding sentence, in any case in which the Secretary of the Treasury determines that the assets of either such Trust Fund would otherwise be inadequate to meet such Fund's obligations for any month, the Secretary of the Treasury shall transfer to such Trust Fund on the first day of such month the amount which would have been transferred to such Fund under this section as in effect on October 1, 1990; and such Trust Fund shall pay interest to the general fund on the amount so transferred on the first day of any month at a rate (calculated on a daily basis, and applied against the difference between the amount so transferred on such first day and the amount which would have been transferred to the Trust Fund up to that day under the procedures in effect on January 1, 1983) equal to the rate earned by the investments of such Fund in the same month under subsection (d)."],[0,"(b) Federal Disability Insurance Trust Fund"],[0,"There is hereby created on the books of the Treasury of the United States a trust fund to be known as the \"Federal Disability Insurance Trust Fund\". The Federal Disability Insurance Trust Fund shall consist of such gifts and bequests as may be made as provided in subsection (i)(1), and such amounts as may be appropriated to, or deposited in, such fund as provided in this section. There is hereby appropriated to the Federal Disability Insurance Trust Fund for the fiscal year ending June 30, 1957, and for each fiscal year thereafter, out of any moneys in the Treasury not otherwise appropriated, amounts equivalent to 100 per centum of—"],[1,"(1)(A) ½ of 1 per centum of the wages (as defined in section 3121 of the Internal Revenue Code of 1954) paid after December 31, 1956, and before January 1, 1966, and reported to the Secretary of the Treasury or his delegate pursuant to subtitle F of the Internal Revenue Code of 1954, (B) 0.70 of 1 per centum of the wages (as so defined) paid after December 31, 1965, and before January 1, 1968, and so reported, (C) 0.95 of 1 per centum of the wages (as so defined) paid after December 31, 1967, and before January 1, 1970, and so reported, (D) 1.10 per centum of the wages (as so defined) paid after December 31, 1969, and before January 1, 1973, and so reported, (E) 1.1 per centum of the wages (as so defined) paid after December 31, 1972, and before January 1, 1974, and so reported, (F) 1.15 per centum of the wages (as so defined) paid after December 31, 1973, and before January 1, 1978, and so reported, (G) 1.55 per centum of the wages (as so defined) paid after December 31, 1977, and before January 1, 1979, and so reported, (H) 1.50 per centum of the wages (as so defined) paid after December 31, 1978, and before January 1, 1980, and so reported, (I) 1.12 per centum of the wages (as so defined) paid after December 31, 1979, and before January 1, 1981, and so reported, (J) 1.30 per centum of the wages (as so defined) paid after December 31, 1980, and before January 1, 1982, and so reported, (K) 1.65 per centum of the wages (as so defined) paid after December 31, 1981, and before January 1, 1983, and so reported, (L) 1.25 per centum of the wages (as so defined) paid after December 31, 1982, and before January 1, 1984, and so reported, (M) 1.00 per centum of the wages (as so defined) paid after December 31, 1983, and before January 1, 1988, and so reported, (N) 1.06 per centum of the wages (as so defined) paid after December 31, 1987, and before January 1, 1990, and so reported, (O) 1.20 per centum of the wages (as so defined) paid after December 31, 1989, and before January 1, 1994, and so reported, (P) 1.88 per centum of the wages (as so defined) paid after December 31, 1993, and before January 1, 1997, and so reported, (Q) 1.70 per centum of the wages (as so defined) paid after December 31, 1996, and before January 1, 2000, and so reported, (R) 1.80 per centum of the wages (as so defined) paid after December 31, 1999, and before January 1, 2016, and so reported, (S) 2.37 per centum of the wages (as so defined) paid after December 31, 2015, and before January 1, 2019, and so reported, and (T) 1.80 per centum of the wages (as so defined) paid after December 31, 2018, and so reported,,1 which wages shall be certified by the Commissioner of Social Security on the basis of the records of wages established and maintained by such Commissioner in accordance with such reports; and"]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/401?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§401. Trust Funds","tname":"The Public Health and Welfare","by":{"0":"1","1":"passim"}},{"t":"usc","label":"42 U.S.C. § 406","url":"https://www.law.cornell.edu/uscode/text/42/406","subs":["(a)","(a)(1)","(a)(2)(A)","(a)(2)(C)","(a)(3)(A)(1)","(b)","(b)(1)(A)","(a)(1976)","(a)(2)","(a)(2)(A)(ii)","(a)(2)(A)(ii)(II)","(a)(2)(A)(iii)","(a)(3)","(a)(3)(A)","(a)(3)(A)(i)","(a)(3)(C)","(a)(4)","(a)(5)","(b)(1)","(b)(2)","(d)","(e)(1)"],"stext":{"head":"§406. Representation of claimants before Commissioner","paras":[[0,"(a) Recognition of representatives; fees for representation before Commissioner"],[0,"(1) The Commissioner of Social Security may prescribe rules and regulations governing the recognition of agents or other persons, other than attorneys as hereinafter provided, representing claimants before the Commissioner of Social Security, and may require of such agents or other persons, before being recognized as representatives of claimants that they shall show that they are of good character and in good repute, possessed of the necessary qualifications to enable them to render such claimants valuable service, and otherwise competent to advise and assist such claimants in the presentation of their cases. An attorney in good standing who is admitted to practice before the highest court of the State, Territory, District, or insular possession of his residence or before the Supreme Court of the United States or the inferior Federal courts, shall be entitled to represent claimants before the Commissioner of Social Security. Notwithstanding the preceding sentences, the Commissioner, after due notice and opportunity for hearing, (A) may refuse to recognize as a representative, and may disqualify a representative already recognized, any attorney who has been disbarred or suspended from any court or bar to which he or she was previously admitted to practice or who has been disqualified from participating in or appearing before any Federal program or agency, and (B) may refuse to recognize, and may disqualify, as a non-attorney representative any attorney who has been disbarred or suspended from any court or bar to which he or she was previously admitted to practice. A representative who has been disqualified or suspended pursuant to this section from appearing before the Social Security Administration as a result of collecting or receiving a fee in excess of the amount authorized shall be barred from appearing before the Social Security Administration as a representative until full restitution is made to the claimant and, thereafter, may be considered for reinstatement only under such rules as the Commissioner may prescribe. The Commissioner of Social Security may, after due notice and opportunity for hearing, suspend or prohibit from further practice before the Commissioner any such person, agent, or attorney who refuses to comply with the Commissioner's rules and regulations or who violates any provision of this section for which a penalty is prescribed. The Commissioner of Social Security may, by rule and regulation, prescribe the maximum fees which may be charged for services performed in connection with any claim before the Commissioner of Social Security under this subchapter, and any agreement in violation of such rules and regulations shall be void. Except as provided in paragraph (2)(A), whenever the Commissioner of Social Security, in any claim before the Commissioner for benefits under this subchapter, makes a determination favorable to the claimant, the Commissioner shall, if the claimant was represented by an attorney in connection with such claim, fix (in accordance with the regulations prescribed pursuant to the preceding sentence) a reasonable fee to compensate such attorney for the services performed by him in connection with such claim."],[0,"(2)(A) In the case of a claim of entitlement to past-due benefits under this subchapter, if—"],[1,"(i) an agreement between the claimant and another person regarding any fee to be recovered by such person to compensate such person for services with respect to the claim is presented in writing to the Commissioner of Social Security prior to the time of the Commissioner's determination regarding the claim,"],[1,"(ii) the fee specified in the agreement does not exceed the lesser of—"],[2,"(I) 25 percent of the total amount of such past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title), or"],[2,"(II) $4,000, and"],[1,"(iii) the determination is favorable to the claimant,"],[0,"then the Commissioner of Social Security shall approve that agreement at the time of the favorable determination, and (subject to paragraph (3)) the fee specified in the agreement shall be the maximum fee. The Commissioner of Social Security may from time to time increase the dollar amount under clause (ii)(II) to the extent that the rate of increase in such amount, as determined over the period since January 1, 1991, does not at any time exceed the rate of increase in primary insurance amounts under section 415(i) of this title since such date. The Commissioner of Social Security shall publish any such increased amount in the Federal Register."],[0,"(B) For purposes of this subsection, the term \"past-due benefits\" excludes any benefits with respect to which payment has been continued pursuant to subsection (g) or (h) of section 423 of this title."],[0,"(C) In any case involving—"],[1,"(i) an agreement described in subparagraph (A) with any person relating to both a claim of entitlement to past-due benefits under this subchapter and a claim of entitlement to past-due benefits under subchapter XVI, and"],[1,"(ii) a favorable determination made by the Commissioner of Social Security with respect to both such claims,"],[0,"the Commissioner of Social Security may approve such agreement only if the total fee or fees specified in such agreement does not exceed, in the aggregate, the dollar amount in effect under subparagraph (A)(ii)(II)."],[0,"(D) In the case of a claim with respect to which the Commissioner of Social Security has approved an agreement pursuant to subparagraph (A), the Commissioner of Social Security shall provide the claimant and the person representing the claimant a written notice of—"],[1,"(i) the dollar amount of the past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title) and the dollar amount of the past-due benefits payable to the claimant,"],[1,"(ii) the dollar amount of the maximum fee which may be charged or recovered as determined under this paragraph, and"],[1,"(iii) a description of the procedures for review under paragraph (3)."],[0,"(3)(A) The Commissioner of Social Security shall provide by regulation for review of the amount which would otherwise be the maximum fee as determined under paragraph (2) if, within 15 days after receipt of the notice provided pursuant to paragraph (2)(D)—"],[1,"(i) the claimant, or the administrative law judge or other adjudicator who made the favorable determination, submits a written request to the Commissioner of Social Security to reduce the maximum fee, or"],[1,"(ii) the person representing the claimant submits a written request to the Commissioner of Social Security to increase the maximum fee."],[0,"Any such review shall be conducted after providing the claimant, the person representing the claimant, and the adjudicator with reasonable notice of such request and an opportunity to submit written information in favor of or in opposition to such request. The adjudicator may request the Commissioner of Social Security to reduce the maximum fee only on the basis of evidence of the failure of the person representing the claimant to represent adequately the claimant's interest or on the basis of evidence that the fee is clearly excessive for services rendered."],[0,"(B)(i) In the case of a request for review under subparagraph (A) by the claimant or by the person representing the claimant, such review shall be conducted by the administrative law judge who made the favorable determination or, if the Commissioner of Social Security determines that such administrative law judge is unavailable or if the determination was not made by an administrative law judge, such review shall be conducted by another person designated by the Commissioner of Social Security for such purpose."],[0,"(ii) In the case of a request by the adjudicator for review under subparagraph (A), the review shall be conducted by the Commissioner of Social Security or by an administrative law judge or other person (other than such adjudicator) who is designated by the Commissioner of Social Security."],[0,"(C) Upon completion of the review, the administrative law judge or other person conducting the review shall affirm or modify the amount which would otherwise be the maximum fee. Any such amount so affirmed or modified shall be considered the amount of the maximum fee which may be recovered under paragraph (2). The decision of the administrative law judge or other person conducting the review shall not be subject to further review."],[0,"(4) Subject to subsection (d), if the claimant is determined to be entitled to past-due benefits under this subchapter and the person representing the claimant is an attorney, the Commissioner of Social Security shall, notwithstanding section 405(i) of this title, certify for payment out of such past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title) to such attorney an amount equal to so much of the maximum fee as does not exceed 25 percent of such past-due benefits (as determined before any applicable reduction under section 1320a–6(a) of this title)."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/406?type=usc&year=mostrecent&link-type=html"},"op":2,"ar":1,"head":"§406. Representation of claimants before Commissioner","tname":"The Public Health and Welfare","by":{"0":"passim, passim, 2, 13, 2, 14, passim, 3, 7, 8","1":"21, 21, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2, 2","2":"17, 18, 19, 7, 2, 10, 22, 7"}},{"t":"usc","label":"42 U.S.C. § 415","url":"https://www.law.cornell.edu/uscode/text/42/415","subs":["(i)"],"by":{"0":"24, 26"}},{"t":"law","label":"Pub. L. No. 99-80","url":"https://www.govinfo.gov/link/statute/99/186","by":{"0":"4, 13","2":"16"}},{"t":"reg","label":"20 C.F.R. § 404.1720","url":"https://www.ecfr.gov/current/title-20/section-404.1720","subs":["(d)"],"by":{"0":"14"}},{"t":"reg","label":"20 C.F.R. § 404.1725","url":"https://www.ecfr.gov/current/title-20/section-404.1725","subs":["(b)(1)","(b)(2)"],"by":{"0":"14, 2"}},{"t":"reg","label":"Maximum Dollar Limit in the Fee Agreement Process, 74 Fed. Reg. 6080","url":"https://www.govinfo.gov/link/fr/74/6080","by":{"0":"2, 7, 14","1":"4, 5"}},{"t":"case","label":"Bowen v. Galbreath","cite":"485 U.S. 74","y":1988,"id":"1987/86-1146","sc":1,"op":2,"sum":"A district court does not have the authority to order the Secretary to withhold a portion of past-due SSI benefits for the payment of attorney's fees received in judicial proceedings under Title XVI. Pp. 75-79. 799 F. 2d 370, reversed.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"2, 8"}},{"t":"case","label":"Fogerty v. Fantasy, Inc.","cite":"510 U.S. 517","y":1994,"id":"1993/92-1750","sc":1,"sum":"The Court held that while attorney's fees are awarded from time to time to prevailing defendants or plaintiffs, this practice is entirely subject to the deciding court's discretion. Indeed, the Court observed, that the statute in question emphasizes such discretion by stating in relevant part that a court \"may\" award attorney's fees.","sumSrc":"Oyez","by":{"1":"24"}},{"t":"case","label":"Shalala v. Schaefer","cite":"509 U.S. 292","y":1993,"id":"1992/92-311","sc":1,"sum":"In 1986, respondent Schaefer filed a claim for Social Security disability benefits, which was denied by petitioner Secretary at the administrative level. Schaefer sought judicial review and, on April 4,1989, the District Court reversed the administrative denial of benefits and remanded the case to the Secretary pursuant to the fourth sentence of 42 U. S. C. § 405(g). Schaefer was awarded benefits on remand and, in …","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"7"}},{"t":"case","label":"Sullivan v. Hudson","cite":"490 U.S. 877","y":1989,"id":"1988/88-616","sc":1,"sum":"It is within a federal court's power under the EAJA to award a Social Security claimant attorney's fees for representation provided during administrative proceedings held pursuant to a district court order remanding the action to the Secretary.","sumSrc":"Syllabus (U.S. Reports)","by":{"1":"6, 7"}},{"t":"case","label":"Wrenn ex rel. Wrenn v. Astrue","cite":"525 F.3d 931","y":2008,"court":"10th Cir.","url":"https://www.courtlistener.com/c/F.3d/525/931/","by":{"1":"22"}},{"t":"usc","label":"5 U.S.C. § 504","url":"https://www.law.cornell.edu/uscode/text/5/504","subs":["(a)(1)"],"by":{"1":"6"}},{"t":"usc","label":"42 U.S.C. § 301","url":"https://www.law.cornell.edu/uscode/text/42/301","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 405","url":"https://www.law.cornell.edu/uscode/text/42/405","subs":["(b)","(g)"],"by":{"1":"2, 2, 5, 6, 7, 10"}},{"t":"usc","label":"42 U.S.C. § 423","url":"https://www.law.cornell.edu/uscode/text/42/423","subs":["(a)"],"stext":{"head":"§423. Disability insurance benefit payments","paras":[[0,"(a) Disability insurance benefits"],[0,"(1) Every individual who—"],[1,"(A) is insured for disability insurance benefits (as determined under subsection (c)(1)),"],[1,"(B) has not attained retirement age (as defined in section 416(l) of this title),"],[1,"(C) if not a United States citizen or national—"],[2,"(i) has been assigned a social security account number that was, at the time of assignment, or at any later time, consistent with the requirements of subclause (I) or (III) of section 405(c)(2)(B)(i) of this title; or"],[2,"(ii) at the time any quarters of coverage are earned—"],[3,"(I) is described in subparagraph (B) or (D) of section 1101(a)(15) of title 8,"],[3,"(II) is lawfully admitted temporarily to the United States for business (in the case of an individual described in such subparagraph (B)) or the performance as a crewman (in the case of an individual described in such subparagraph (D)), and"],[3,"(III) the business engaged in or service as a crewman performed is within the scope of the terms of such individual's admission to the United States.1"],[1,"(D) has filed application for disability insurance benefits, and"],[1,"(E) is under a disability (as defined in subsection (d))"],[0,"shall be entitled to a disability insurance benefit (i) for each month beginning with the first month after his waiting period (as defined in subsection (c)(2)) in which he becomes so entitled to such insurance benefits, (ii) in the case of an individual who has been medically determined to have amyotrophic lateral sclerosis, for each month beginning with the first month during all of which the individual is under a disability and in which the individual becomes entitled to such insurance benefits, or (iii) for each month beginning with the first month during all of which he is under a disability and in which he becomes so entitled to such insurance benefits, but only if he was entitled to disability insurance benefits which terminated, or had a period of disability (as defined in section 416(i) of this title) which ceased, within the 60-month period preceding the first month in which he is under such disability, and ending with the month preceding whichever of the following months is the earliest: the month in which he dies, the month in which he attains retirement age (as defined in section 416(l) of this title), or, subject to subsection (e), the termination month. For purposes of the preceding sentence, the termination month for any individual shall be the third month following the month in which his disability ceases; except that, in the case of an individual who has a period of trial work which ends as determined by application of section 422(c)(4)(A) of this title, the termination month shall be the earlier of (I) the third month following the earliest month after the end of such period of trial work with respect to which such individual is determined to no longer be suffering from a disabling physical or mental impairment, or (II) the third month following the earliest month in which such individual engages or is determined able to engage in substantial gainful activity, but in no event earlier than the first month occurring after the 36 months following such period of trial work in which he engages or is determined able to engage in substantial gainful activity. No payment under this paragraph may be made to an individual who would not meet the definition of disability in subsection (d) except for paragraph (1)(B) thereof for any month in which he engages in substantial gainful activity, and no payment may be made for such month under subsection (b), (c), or (d) of section 402 of this title to any person on the basis of the wages and self-employment income of such individual. In the case of a deceased individual, the requirement of subparagraph (C) may be satisfied by an application for benefits filed with respect to such individual within 3 months after the month in which he died."],[0,"(2) Except as provided in section 402(q) of this title and section 415(b)(2)(A)(ii) of this title, such individual's disability insurance benefit for any month shall be equal to his primary insurance amount for such month determined under section 415 of this title as though he had attained age 62 in—"],[1,"(A) the first month of his waiting period, or"],[1,"(B) in any case in which clause (ii) of paragraph (1) of this subsection is applicable, the first month for which he becomes entitled to such disability insurance benefits,"],[0,"and as though he had become entitled to old-age insurance benefits in the month in which the application for disability insurance benefits was filed and he was entitled to an old-age insurance benefit for each month for which (pursuant to subsection (b)) he was entitled to a disability insurance benefit. For the purposes of the preceding sentence, in the case of an individual who attained age 62 in or before the first month referred to in subparagraph (A) or (B) of such sentence, as the case may be, the elapsed years referred to in section 415(b)(3) of this title shall not include the year in which he attained age 62, or any year thereafter."],[0,"(b) Filing application"],[0,"An application for disability insurance benefits filed before the first month in which the applicant satisfies the requirements for such benefits (as prescribed in subsection (a)(1)) shall be deemed a valid application (and shall be deemed to have been filed in such first month) only if the applicant satisfies the requirements for such benefits before the Commissioner of Social Security makes a final decision on the application and no request under section 405(b) of this title for notice and opportunity for a hearing thereon is made, or if such a request is made, before a decision based upon the evidence adduced at the hearing is made (regardless of whether such decision becomes the final decision of the Commissioner of Social Security). An individual who would have been entitled to a disability insurance benefit for any month had he filed application therefor before the end of such month shall be entitled to such benefit for such month if such application is filed before the end of the 12th month immediately succeeding such month."],[0,"(c) Definitions; insured status; waiting period"],[0,"For purposes of this section—"],[1,"(1) An individual shall be insured for disability insurance benefits in any month if—"],[2,"(A) he would have been a fully insured individual (as defined in section 414 of this title) had he attained age 62 and filed application for benefits under section 402(a) of this title on the first day of such month, and"],[2,"(B)(i) he had not less than 20 quarters of coverage during the 40-quarter period which ends with the quarter in which such month occurred, or"],[2,"(ii) if such month ends before the quarter in which he attains (or would attain) age 31, not less than one-half (and not less than 6) of the quarters during the period ending with the quarter in which such month occurred and beginning after he attained the age of 21 were quarters of coverage, or (if the number of quarters in such period is less than 12) not less than 6 of the quarters in the 12-quarter period ending with such quarter were quarters of coverage, or"],[2,"(iii) in the case of an individual (not otherwise insured under clause (i)) who, by reason of section 416(i)(3)(B)(ii) of this title, had a prior period of disability that began during a period before the quarter in which he or she attained age 31, not less than one-half of the quarters beginning after such individual attained age 21 and ending with the quarter in which such month occurs are quarters of coverage, or (if the number of quarters in such period is less than 12) not less than 6 of the quarters in the 12-quarter period ending with such quarter are quarters of coverage;"],[1,"except that the provisions of subparagraph (B) of this paragraph shall not apply in the case of an individual who is blind (within the meaning of \"blindness\" as defined in section 416(i)(1) of this title). For purposes of subparagraph (B) of this paragraph, when the number of quarters in any period is an odd number, such number shall be reduced by one, and a quarter shall not be counted as part of any period if any part of such quarter was included in a period of disability unless such quarter was a quarter of coverage."],[1,"(2) The term \"waiting period\" means, in the case of any application for disability insurance benefits, the earliest period of five consecutive calendar months—"],[2,"(A) throughout which the individual with respect to whom such application is filed has been under a disability, and"],[2,"(B)(i) which begins not earlier than with the first day of the seventeenth month before the month in which such application is filed if such individual is insured for disability insurance benefits in such seventeenth month, or (ii) if he is not so insured in such month, which begins not earlier than with the first day of the first month after such seventeenth month in which he is so insured."],[1,"Notwithstanding the preceding provisions of this paragraph, no waiting period may begin for any individual before January 1, 1957."]],"more":true,"ed":"2024","src":"https://www.govinfo.gov/link/uscode/42/423?type=usc&year=mostrecent&link-type=html"},"op":1,"head":"§423. Disability insurance benefit payments","tname":"The Public Health and Welfare","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1381","url":"https://www.law.cornell.edu/uscode/text/42/1381","by":{"1":"2, 3, 5, 17"}},{"t":"usc","label":"42 U.S.C. § 1382","url":"https://www.law.cornell.edu/uscode/text/42/1382","by":{"1":"2"}},{"t":"usc","label":"42 U.S.C. § 1383","url":"https://www.law.cornell.edu/uscode/text/42/1383","subs":["(c)(1)","(c)(2)","(c)(3)","(d)(2)(A)","(d)(2)(B)"],"by":{"1":"2, 2, 2, 3, 3"}},{"t":"case","label":"Alexander v. Sandoval","cite":"532 U.S. 275","y":2001,"id":"2000/99-1908","sc":1,"sum":"The Court held that there is no private right of action to enforce disparate-impact regulations promulgated under Title VI. \"Title VI itself directly reaches only instances of intentional discrimination,\" wrote Justice Scalia, \"[n]either as originally enacted nor as later amended does Title VI display an intent to create a freestanding private right of action to enforce regulations promulgated under [section 602].\" Justice John Paul Stevens filed a dissenting opinion, which was join by Justices David H. Souter, Ruth Bader Ginsburg, and Stephen G. Breyer.","sumSrc":"Oyez","by":{"2":"4"}},{"t":"case","label":"Astrue v. Ratliff","cite":"560 U.S. 586","y":2010,"id":"2009/08-1322","sc":1,"sum":"The Court determined that an award of attorney’s fees under the Equal Access to Justice Act can be used to offset the prevailing party’s preexisting debt to the government.","sumSrc":"Oyez","by":{"2":"16, 17"}},{"t":"case","label":"Bailey v. Heckler","cite":"621 F. Supp. 521","y":1985,"court":"W.D. Pa.","url":"https://www.courtlistener.com/c/F.%20Supp./621/521/","by":{"2":"10"}},{"t":"case","label":"Barnhart v. Walton","cite":"535 U.S. 212","y":2002,"id":"2001/00-1937","sc":1,"sum":"The Court held that the Social Security Administration's interpretations of the statute fell within its lawful interpretative authority.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"BedRoc Ltd., LLC v. United States","cite":"541 U.S. 176","y":2004,"id":"2003/02-1593","sc":1,"sum":"The Court ruled that because sand and gravel were not commercially valuable in 1919 when the Pittman Act was passed, they were not \"valuable minerals\" covered under the Act.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Brown v. Gardner","cite":"387 F.2d 345","y":1967,"court":"4th Cir.","url":"https://www.courtlistener.com/c/F.2d/387/345/","by":{"2":"10"}},{"t":"case","label":"Claypool v. Barnhart","cite":"294 F. Supp. 2d 829","y":2003,"court":"S.D.W. Va.","url":"https://www.courtlistener.com/c/F.%20Supp.%202d/294/829/","by":{"2":"14-15"}},{"t":"case","label":"Demarest v. Manspeaker","cite":"498 U.S. 184","y":1991,"id":"1990/89-5916","sc":1,"sum":"Section 1821 requires payment of witness fees to a convicted state prisoner who testifies at a federal trial pursuant to a writ of habeas corpus ad testificandum. The statute's terms make virtually inescapable the conclusion that a \"witness in attendance at any court of the United States\" under § 1821(a)(1) includes prisoners unless they are otherwise excepted in the statute. That Congress was thinking about …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"3"}},{"t":"case","label":"Dig. Realty Tr., Inc. v. Somers","cite":"138 S. Ct. 767","y":2018,"id":"2017/16-1276","sc":1,"sum":"The Court held that the anti-retaliation provision for \"whistleblowers\" in the Dodd-Frank Wall Street Reform and Consumer Protection Act of 2010 applies only to individuals who fall within the act’s specific definition of \"whistleblower,\" that is, those who disclose allegedly unlawful activity to the Securities and Exchange Commission.","sumSrc":"Oyez","by":{"2":"5"}},{"t":"case","label":"Horenstein v. Sec’y of Health & Human Servs.","cite":"35 F.3d 261","y":1994,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.3d/35/261/","ar":2,"by":{"2":"3, 12"}},{"t":"case","label":"Lavender v. Califano","cite":"683 F.2d 133","y":1982,"court":"6th Cir.","url":"https://www.courtlistener.com/c/F.2d/683/133/","sum":"Holding that “the district court judge is empowered to make the fee determination”.","sumSrc":"brief:2","by":{"2":"10"}},{"t":"case","label":"Lorillard v. Pons","cite":"434 U.S. 575","y":1978,"id":"1977/76-1346","sc":1,"sum":"Yes. Although the ADEA does not expressly provide for jury trials, its structure shows that Congress intended a jury to be available in private ADEA actions when a party seeks one. The Court therefore did not reach the Seventh Amendment question.","sumSrc":"AI-generated brief","by":{"2":"4"}},{"t":"case","label":"Melvin v. Colvin","cite":"2013 WL 3340490","y":2013,"court":"E.D.N.C. July 2","by":{"2":"14"}},{"t":"case","label":"Nat’l Ass’n of Mfrs. v. Dep’t of Def.","cite":"138 S. Ct. 617","y":2018,"id":"2017/16-299","sc":1,"sum":"The Court decided that challenges to the Environmental Protection Agency’s rule that defines the scope of United States waters must be filed in federal district courts.","sumSrc":"Oyez","by":{"2":"22"}},{"t":"case","label":"Pierce v. Underwood","cite":"487 U.S. 552","y":1988,"id":"1987/86-1512","sc":1,"sum":"One of petitioner's predecessors as Secretary of Housing and Urban Development decided not to implement an \"operating subsidy\" program authorized by federal statute, which was intended to provide payments to owners of Government-subsidized apartment buildings to offset rising utility expenses and property taxes. Various plaintiffs, including respondent members of a nationwide class of Government-subsidized housing …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"16, 17"}},{"t":"case","label":"Pub. Emps. Ret. Sys. of Ohio v. Betts","cite":"492 U.S. 158","y":1989,"id":"1988/88-389","sc":1,"sum":"Section 4(f)(2) exempts all provisions of bona fide employee benefit plans from the purview of the ADEA, unless the plan is a subterfuge for discrimination in the non-fringe-benefit aspects of the employment relationship, and summary judgment for appellee was therefore inappropriate.","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"12"}},{"t":"case","label":"Rodriguez v. United States","cite":"480 U.S. 522","y":1987,"id":"1986/86-5504","sc":1,"sum":"Section 3147 does not divest sentencing judges of their § 3651 authority. Nothing in the language of the two provisions suggests the existence of an \"irreconcilable conflict\" from which an intent to work an implicit partial repeal of § 3651 may be inferred; to the contrary, the provisions fit together quite sensibly. Moreover, the totality of the legislative history of the Act of which §3147 is a part demonstrates …","sumSrc":"Syllabus (U.S. Reports)","by":{"2":"6"}},{"t":"case","label":"Sabourin v. Colvin","cite":"2014 WL 3949506","y":2014,"court":"N.D. Tex. Aug. 12","by":{"2":"14"}},{"t":"case","label":"Salinger v. Loisel","cite":"265 U.S. 224","y":1924,"id":"scdb/1923-152","sc":1,"sum":"1. Warrants of removal issued in triplicate are in legal effect but a single warrant, and defendant who had secured a supersedeas on appeal from an order refusing relief by habeas corpus from arrest under one, could not lawfully be arrested under another.","sumSrc":"Headnote (U.S. Reports)","by":{"2":"9"}},{"t":"case","label":"Vilkas v. Comm’r of Soc. Sec.","cite":"2007 WL 1498115","y":2007,"court":"M.D. Fla. May 14","by":{"2":"14"}},{"t":"case","label":"Wells v. Sullivan","cite":"907 F.2d 367","y":1990,"court":"2d Cir.","url":"https://www.courtlistener.com/c/F.2d/907/367/","by":{"2":"16"}},{"t":"usc","label":"42 U.S.C. § 407","url":"https://www.law.cornell.edu/uscode/text/42/407","subs":["(a)"],"by":{"2":"20"}},{"t":"law","label":"Pub. L. No. 101-508","url":"https://www.govinfo.gov/link/statute/104/1388","by":{"2":"4"}},{"t":"reg","label":"20 C.F.R. § 404.1820","url":"https://www.ecfr.gov/current/title-20/section-404.1820","subs":["(a)(2)"],"by":{"2":"20"}}]};